(85, 8, 68, 'package.json', '.json', 'text/plain', '{\n  \"name\": \"frontend\",\n  \"private\": true,\n  \"version\": \"0.0.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"vite\",\n    \"build\": \"vite build\",\n    \"lint\": \"eslint .\",\n    \"preview\": \"vite preview\"\n  },\n  \"dependencies\": {\n    \"react\": \"^19.2.7\",\n    \"react-dom\": \"^19.2.7\"\n  },\n  \"devDependencies\": {\n    \"@eslint/js\": \"^10.0.1\",\n    \"@types/react\": \"^19.2.17\",\n    \"@types/react-dom\": \"^19.2.3\",\n    \"@vitejs/plugin-react\": \"^6.0.3\",\n    \"eslint\": \"^10.6.0\",\n    \"eslint-plugin-react-hooks\": \"^7.1.1\",\n    \"eslint-plugin-react-refresh\": \"^0.5.3\",\n    \"globals\": \"^17.7.0\",\n    \"vite\": \"^8.1.1\"\n  }\n}\n', 604, 1, NULL, 0, '2026-07-13 17:13:53', '2026-07-13 17:13:53', NULL),
(86, 8, 68, 'README.md', '.md', 'text/plain', '# React + Vite\n\nThis template provides a minimal setup to get React working in Vite with HMR and some ESLint rules.\n\nCurrently, two official plugins are available:\n\n- [@vitejs/plugin-react](https://github.com/vitejs/vite-plugin-react/blob/main/packages/plugin-react) uses [Oxc](https://oxc.rs)\n- [@vitejs/plugin-react-swc](https://github.com/vitejs/vite-plugin-react/blob/main/packages/plugin-react-swc) uses [SWC](https://swc.rs/)\n\n## React Compiler\n\nThe React Compiler is not enabled on this template because of its impact on dev & build performances. To add it, see [this documentation](https://react.dev/learn/react-compiler/installation).\n\n## Expanding the ESLint configuration\n\nIf you are developing a production application, we recommend using TypeScript with type-aware lint rules enabled. Check out the [TS template](https://github.com/vitejs/vite/tree/main/packages/create-vite/template-react-ts) for information on how to integrate TypeScript and [`typescript-eslint`](https://typescript-eslint.io) in your project.\n', 1027, 1, NULL, 0, '2026-07-13 17:13:53', '2026-07-13 17:13:53', NULL),
(87, 8, 68, 'vite.config.js', '.js', 'text/plain', 'import { defineConfig } from \'vite\'\nimport react from \'@vitejs/plugin-react\'\n\n// https://vite.dev/config/\nexport default defineConfig({\n  plugins: [react()],\n})\n', 161, 1, NULL, 0, '2026-07-13 17:13:53', '2026-07-13 17:13:53', NULL),
(88, 8, 69, '.gitignore', '.gitignore', 'text/plain', '# Logs\nlogs\n*.log\nnpm-debug.log*\nyarn-debug.log*\nyarn-error.log*\npnpm-debug.log*\nlerna-debug.log*\n\nnode_modules\ndist\ndist-ssr\n*.local\n\n# Editor directories and files\n.vscode/*\n!.vscode/extensions.json\n.idea\n.DS_Store\n*.suo\n*.ntvs*\n*.njsproj\n*.sln\n*.sw?\n', 253, 1, NULL, 0, '2026-07-13 17:13:53', '2026-07-13 17:13:53', NULL),
(89, 8, 69, 'eslint.config.js', '.js', 'text/plain', 'import js from \'@eslint/js\'\nimport globals from \'globals\'\nimport reactHooks from \'eslint-plugin-react-hooks\'\nimport reactRefresh from \'eslint-plugin-react-refresh\'\nimport { defineConfig, globalIgnores } from \'eslint/config\'\n\nexport default defineConfig([\n  globalIgnores([\'dist\']),\n  {\n    files: [\'**/*.{js,jsx}\'],\n    extends: [\n      js.configs.recommended,\n      reactHooks.configs.flat.recommended,\n      reactRefresh.configs.vite,\n    ],\n    languageOptions: {\n      globals: globals.browser,\n      parserOptions: { ecmaFeatures: { jsx: true } },\n    },\n  },\n])\n', 568, 1, NULL, 0, '2026-07-13 17:13:53', '2026-07-13 17:13:53', NULL),
(90, 8, 69, 'index.html', '.html', 'text/plain', '<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <link rel=\"icon\" type=\"image/svg+xml\" href=\"/favicon.svg\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>frontend</title>\n  </head>\n  <body>\n    <div id=\"root\"></div>\n    <script type=\"module\" src=\"/src/main.jsx\"></script>\n  </body>\n</html>\n', 360, 1, NULL, 0, '2026-07-13 17:13:53', '2026-07-13 17:13:53', NULL);
