(532, 19, 191, 'index.css', '.css', 'text/plain', ':root {\n  --text: #6b6375;\n  --text-h: #08060d;\n  --bg: #fff;\n  --border: #e5e4e7;\n  --code-bg: #f4f3ec;\n  --accent: #aa3bff;\n  --accent-bg: rgba(170, 59, 255, 0.1);\n  --accent-border: rgba(170, 59, 255, 0.5);\n  --social-bg: rgba(244, 243, 236, 0.5);\n  --shadow:\n    rgba(0, 0, 0, 0.1) 0 10px 15px -3px, rgba(0, 0, 0, 0.05) 0 4px 6px -2px;\n\n  --sans: system-ui, \'Segoe UI\', Roboto, sans-serif;\n  --heading: system-ui, \'Segoe UI\', Roboto, sans-serif;\n  --mono: ui-monospace, Consolas, monospace;\n\n  font: 18px/145% var(--sans);\n  letter-spacing: 0.18px;\n  color-scheme: light dark;\n  color: var(--text);\n  background: var(--bg);\n  font-synthesis: none;\n  text-rendering: optimizeLegibility;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n\n  @media (max-width: 1024px) {\n    font-size: 16px;\n  }\n}\n\n@media (prefers-color-scheme: dark) {\n  :root {\n    --text: #9ca3af;\n    --text-h: #f3f4f6;\n    --bg: #16171d;\n    --border: #2e303a;\n    --code-bg: #1f2028;\n    --accent: #c084fc;\n    --accent-bg: rgba(192, 132, 252, 0.15);\n    --accent-border: rgba(192, 132, 252, 0.5);\n    --social-bg: rgba(47, 48, 58, 0.5);\n    --shadow:\n      rgba(0, 0, 0, 0.4) 0 10px 15px -3px, rgba(0, 0, 0, 0.25) 0 4px 6px -2px;\n  }\n\n  #social .button-icon {\n    filter: invert(1) brightness(2);\n  }\n}\n\nbody {\n  margin: 0;\n}\n\n#root {\n  width: 1126px;\n  max-width: 100%;\n  margin: 0 auto;\n  text-align: center;\n  border-inline: 1px solid var(--border);\n  min-height: 100svh;\n  display: flex;\n  flex-direction: column;\n  box-sizing: border-box;\n}\n\nh1,\nh2 {\n  font-family: var(--heading);\n  font-weight: 500;\n  color: var(--text-h);\n}\n\nh1 {\n  font-size: 56px;\n  letter-spacing: -1.68px;\n  margin: 32px 0;\n  @media (max-width: 1024px) {\n    font-size: 36px;\n    margin: 20px 0;\n  }\n}\nh2 {\n  font-size: 24px;\n  line-height: 118%;\n  letter-spacing: -0.24px;\n  margin: 0 0 8px;\n  @media (max-width: 1024px) {\n    font-size: 20px;\n  }\n}\np {\n  margin: 0;\n}\n\ncode,\n.counter {\n  font-family: var(--mono);\n  display: inline-flex;\n  border-radius: 4px;\n  color: var(--text-h);\n}\n\ncode {\n  font-size: 15px;\n  line-height: 135%;\n  padding: 4px 8px;\n  background: var(--code-bg);\n}\n', 2169, 1, NULL, 1, '2026-08-04 15:51:10', '2026-08-04 15:52:50', '2026-08-04 10:22:50'),
(533, 19, 191, 'main.jsx', '.jsx', 'text/plain', 'import { StrictMode } from \'react\'\nimport { createRoot } from \'react-dom/client\'\nimport \'./index.css\'\nimport App from \'./App.jsx\'\n\ncreateRoot(document.getElementById(\'root\')).render(\n  <StrictMode>\n    <App />\n  </StrictMode>,\n)\n', 229, 1, NULL, 1, '2026-08-04 15:51:10', '2026-08-04 15:52:50', '2026-08-04 10:22:50'),
(534, 19, 189, 'vite.config.js', '.js', 'text/plain', 'import { defineConfig } from \'vite\'\nimport react from \'@vitejs/plugin-react\'\n\n// https://vite.dev/config/\nexport default defineConfig({\n  plugins: [react()],\n})\n', 161, 1, NULL, 1, '2026-08-04 15:51:10', '2026-08-04 15:52:50', '2026-08-04 10:22:50'),
(535, 19, 189, '.gitignore', '.gitignore', 'text/plain', '# Logs\nlogs\n*.log\nnpm-debug.log*\nyarn-debug.log*\nyarn-error.log*\npnpm-debug.log*\nlerna-debug.log*\n\nnode_modules\ndist\ndist-ssr\n*.local\n\n# Editor directories and files\n.vscode/*\n!.vscode/extensions.json\n.idea\n.DS_Store\n*.suo\n*.ntvs*\n*.njsproj\n*.sln\n*.sw?\n', 253, 1, NULL, 1, '2026-08-04 15:51:10', '2026-08-04 15:52:50', '2026-08-04 10:22:50'),
(536, 19, 189, '.oxlintrc.json', '.json', 'text/plain', '{\n  \"$schema\": \"./node_modules/oxlint/configuration_schema.json\",\n  \"plugins\": [\"react\", \"oxc\"],\n  \"rules\": {\n    \"react/rules-of-hooks\": \"error\",\n    \"react/only-export-components\": [\"warn\", { \"allowConstantExport\": true }]\n  }\n}\n', 231, 1, NULL, 1, '2026-08-04 15:51:10', '2026-08-04 15:52:50', '2026-08-04 10:22:50'),
(537, 19, 189, 'package.json', '.json', 'text/plain', '{\n  \"name\": \"npc\",\n  \"private\": true,\n  \"version\": \"0.0.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"vite\",\n    \"build\": \"vite build\",\n    \"lint\": \"oxlint\",\n    \"preview\": \"vite preview\"\n  },\n  \"dependencies\": {\n    \"react\": \"^19.2.8\",\n    \"react-dom\": \"^19.2.8\"\n  },\n  \"devDependencies\": {\n    \"@types/react\": \"^19.2.17\",\n    \"@types/react-dom\": \"^19.2.3\",\n    \"@vitejs/plugin-react\": \"^6.0.4\",\n    \"oxlint\": \"^1.75.0\",\n    \"vite\": \"^8.2.0\"\n  }\n}\n', 454, 1, NULL, 1, '2026-08-04 15:51:10', '2026-08-04 15:52:50', '2026-08-04 10:22:50');
